def _backfill_request_keys() -> None:
    """Copy retained keys in bounded pages; deleted results need no tombstone."""
    connection = op.get_bind()
    tables = set(sa.inspect(connection).get_table_names())
    direct = {
        "agent.duplicate": "agents",
        "application_account.create": "application_accounts",
        "account_target.create": "account_targets",
        "asset.upload": "assets",
        "bot_test.create": "bot_tests",
        "configuration.session.create": "sessions",
        "configuration.thread.create": "threads",
        "thread.create": "threads",
        "connection.create": "connections",
        "connector_provider.create": "connector_providers",
        "connector_connection.setup": "connection_authorizations",
        "connection.authorize": "connection_authorizations",
        "mcp_connection.authorize": "connection_authorizations",
        "environment_template.create": "environment_templates",
        "environment.create": "environments",
        "environment.command": "environment_commands",
    }
    cursor = ""
    while (
        rows := connection.execute(
            sa.text("SELECT * FROM idempotency_evidence WHERE id > :cursor ORDER BY id LIMIT 500"), {"cursor": cursor}
        )
        .mappings()
        .all()
    ):
        for row in rows:
            cursor = row["id"]
            operation = row["operation"]
            receipt = row["receipt_json"] or {}
            key = hashlib.sha256(
                json.dumps(
                    (
                        row["boundary_scope_id"],
                        row["actor_type"],
                        row["actor_id"],
                        "connection.authorize"
                        if operation in {"connector_connection.setup", "mcp_connection.authorize"}
                        else operation,
                        row["scope_id"],
                        row["key_digest"],
                    ),
                    separators=(",", ":"),
                    ensure_ascii=False,
                ).encode()
            ).hexdigest()
            table = direct.get(operation)
            column = "request_key"
            identifier = row["result_ref"]
            predicate = "id = :identifier"
            params = {"identifier": identifier, "key": key, "scope": row["scope_id"]}
            if operation == "agent.create":
                table, identifier = "agents", receipt.get("agent", {}).get("id")
            elif operation == "skill.create":
                table, identifier = "skills", receipt.get("response", {}).get("skill", {}).get("id")
            elif operation == "skill_upload.stage":
                table, identifier = "skill_uploads", receipt.get("response", {}).get("upload_id")
            elif operation == "skill.revision.publish":
                revision_id = receipt.get("response", {}).get("revision", {}).get("id")
                if revision_id:
                    connection.execute(
                        sa.text(
                            "UPDATE idempotency_evidence SET result_kind = 'skill_revision', result_ref = :ref WHERE id = :id"
                        ),
                        {"ref": revision_id, "id": row["id"]},
                    )
            elif operation == "run.accept":
                if row["result_kind"] == "queue_consumption":
                    table, column = "thread_queued_submissions", "consumption_key"
                    identifier = receipt.get("queued_submission", {}).get("queued_submission_id")
                else:
                    table = "runs"
            elif operation == "thread.submit":
                if receipt.get("outcome") == "queued":
                    table, identifier = (
                        "thread_queued_submissions",
                        receipt.get("queued_submission", {}).get("queued_submission_id"),
                    )
                else:
                    table, identifier = "runs", receipt.get("run", {}).get("run_id")
            elif operation == "queue.enqueue":
                table, identifier = (
                    "thread_queued_submissions",
                    receipt.get("queued_submission", {}).get("queued_submission_id"),
                )
            elif operation == "queue.update":
                identifier = receipt.get("queued_submission", {}).get("queued_submission_id")
                if identifier:
                    connection.execute(
                        sa.text(
                            "UPDATE idempotency_evidence SET result_kind = 'queued_submission', result_ref = :ref WHERE id = :id"
                        ),
                        {"ref": identifier, "id": row["id"]},
                    )
            elif operation == "run.interrupt":
                table, column = "runs", "interrupt_key"
            elif operation == "run.environment_mount.add":
                table, predicate = "run_environment_mounts", "name = :identifier AND run_id = :scope"
            elif operation == "configuration.draft.discard":
                table, column, identifier = "configuration_drafts", "discard_key", row["scope_id"]
                params["key"] = row["key_digest"]
            elif operation in {"connector_connection.delete", "mcp_connection.delete"}:
                table, column = "connections", "deletion_key"
            if operation in {"connector_connection.delete", "connector_connection.revoke", "mcp_connection.delete"}:
                resource = receipt.get("resource", {})
                connection.execute(
                    sa.text(
                        "UPDATE connections SET cleanup_version = :version, remote_cleanup_status = :status WHERE id = :id AND (cleanup_version IS NULL OR cleanup_version < :version)"
                    ),
                    {
                        "id": row["result_ref"],
                        "version": receipt.get("version", 0),
                        "status": resource.get("remote_status", "unknown"),
                    },
                )
            if operation == "connector_provider.test":
                resource = receipt.get("resource", {})
                if resource.get("tested_at"):
                    connection.execute(
                        sa.text(
                            "UPDATE connector_providers SET tested_at = :tested_at, tested_version = :version, verified_access = CAST(:access AS json) WHERE id = :id AND (tested_at IS NULL OR tested_at < CAST(:tested_at AS timestamptz))"
                        ),
                        {
                            "id": row["result_ref"],
                            "tested_at": resource["tested_at"],
                            "version": resource["connector_provider_version"],
                            "access": json.dumps(resource["verified_access"]),
                        },
                    )
            if table in tables and identifier:
                params["identifier"] = identifier
                connection.execute(
                    sa.text(f"UPDATE {table} SET {column} = :key WHERE {predicate} AND {column} IS NULL"), params
                )
                connection.execute(sa.text("DELETE FROM idempotency_evidence WHERE id = :id"), {"id": row["id"]})
            elif operation == "configuration.draft.apply":
                application = (
                    connection.execute(
                        sa.text(
                            "SELECT id, key_hash FROM configuration_applications WHERE draft_id = :draft AND reviewed_version = :version"
                        ),
                        {"draft": row["scope_id"], "version": receipt.get("reviewed_version")},
                    )
                    .mappings()
                    .first()
                )
                if application and application["key_hash"] == row["key_digest"]:
                    connection.execute(sa.text("DELETE FROM idempotency_evidence WHERE id = :id"), {"id": row["id"]})
                elif application:
                    connection.execute(
                        sa.text(
                            "UPDATE idempotency_evidence SET result_kind = 'configuration_application', result_ref = :ref WHERE id = :id"
                        ),
                        {"ref": application["id"], "id": row["id"]},
                    )
            elif operation == "queue.delete":
                connection.execute(sa.text("DELETE FROM idempotency_evidence WHERE id = :id"), {"id": row["id"]})


def _backfill_applications() -> None:
    fields = {
        "reviewed_digest": "text",
        "reviewed_mode": "text",
        "reviewed_target_agent_id": "text",
        "reviewed_base_agent_revision_id": "text",
        "reviewed_creation_metadata": "json",
        "agent_id": "text",
        "agent_revision_version": "bigint",
        "applied_by_user_id": "text",
        "no_change": "boolean",
        "verification_acknowledgement": "json",
        "verification_run_ids": "json",
    }
    assignments = ", ".join(
        f"{name} = CAST(receipt {'->' if kind == 'json' else '->>'} '{name}' AS {kind})"
        for name, kind in fields.items()
    )
    connection = op.get_bind()
    cursor = ""
    while (
        identifiers := connection.execute(
            sa.text("SELECT id FROM configuration_applications WHERE id > :cursor ORDER BY id LIMIT 500"),
            {"cursor": cursor},
        )
        .scalars()
        .all()
    ):
        end = identifiers[-1]
        connection.execute(
            sa.text(f"UPDATE configuration_applications SET {assignments} WHERE id > :cursor AND id <= :end"),
            {"cursor": cursor, "end": end},
        )
        cursor = end
    for name in (
        "reviewed_digest",
        "reviewed_mode",
        "agent_id",
        "agent_revision_version",
        "applied_by_user_id",
        "no_change",
        "verification_run_ids",
    ):
        op.alter_column("configuration_applications", name, nullable=False)


